import { CommonModule } from '@angular/common';
import { Component, EventEmitter, Input, Output } from '@angular/core';

//#region Types
/* ----- Badge Types ----- */
type BadgeColor = 'gray' | 'green' | 'red' | 'orange' | 'purple' | 'teal';
type BadgeAppearance = 'solid' | 'subtle' | 'outline';
type BadgeSize = 'sm' | 'md' | 'lg';
type BadgeShape = 'rounded' | 'pill' | 'square';
type IconPosition = 'start' | 'end';
type AnimationType = 'none' | 'pop' | 'pulse' | 'fade';
//#endregion

//#region Badge Config Interface
/* ----- Badge Config Interface ----- */
export interface BadgeConfig {
  color: string;
  label?: string;
  icon?: string;
  show?: boolean;
}
//#endregion
@Component({
  selector: 'app-badge',
  imports: [CommonModule],
  templateUrl: './badge.html',
  styleUrl: './badge.scss',
})
export class Badge {
  //#region Inputs and Outputs
  /* ----- Inputs and Outputs ----- */
  @Input() color: BadgeColor = 'gray';
  @Input() appearance: BadgeAppearance = 'solid';
  @Input() label?: string;
  @Input() size: BadgeSize = 'md';
  @Input() shape: BadgeShape = 'rounded';
  @Input() icon?: string;
  @Input() iconPosition: IconPosition = 'start';
  @Input() badges?: BadgeConfig[];
  @Input() show = true;
  @Input() isClickable = false;
  @Input() disabled = false;
  @Input() backgroundColor?: string;
  @Input() textColor?: string;
  @Input() borderColor?: string;
  @Input() animation: AnimationType = 'none';
  @Output() onClick = new EventEmitter<void>();
  //#endregion

  //#region Methods
  /** Compute ARIA label for accessibility */
  public get ariaLabel() {
    const parts = [];
    if (this.label) parts.push(this.label);
    return parts.join(' ') || 'badge';
  }

  /** Handle badge click event */
  public handleClick(): void {
    if (this.isClickable && !this.disabled) {
      this.onClick.emit();
    }
  }
  //#endregion
}

import { CommonModule, DatePipe } from '@angular/common';
import { Component, ElementRef, HostListener, Input, OnChanges, OnInit, SimpleChanges, ViewChild } from '@angular/core';
import { FormsModule } from '@angular/forms';
/* ------ Interfaces ------ */
/**
 * Represents single calendar day
 */
interface Day {
  date: Date;
  currentMonth: boolean;
  selected?: boolean;
  inRange?: boolean;
  rangeStart?: boolean;
  rangeEnd?: boolean;
}
/**
 * Represents year item in picker
 */
interface YearItem {
  value: number;
  disabled: boolean;
}

@Component({
  selector: 'app-date-picker',
  imports: [CommonModule, DatePipe, FormsModule],
  templateUrl: './date-picker.html',
  styleUrl: './date-picker.scss',
})
export class DatePicker implements OnInit, OnChanges {
  /* ----- Inputs ----- */
  /**
   * Picker mode
   * single -> single date
   * range -> date range
   */
  @Input() type: 'single' | 'range' = 'single';
  /**
   * Calendar icon optional
   */
  @Input() icon?: string;
  /**
   * Disable past years
   */
  @Input() noPastYears = false;
  /**
   * Disable future years
   */
  @Input() noFutureYears = false;
  /**
   * Limit number of past years
   */
  @Input() pastYearLimit: number | null = null;
  /**
   * Limit number of future years
   */
  @Input() futureYearLimit: number | null = null;
  /* Internal states */
  /** Show date picker popup */
  show = false;
  /**Show year selector */
  showYearPicker = false;
  /**Current visible month */
  currentMonth = new Date();
  /**Temporary selected year */
  tempYear!: number;
  /**Calendar grid days */
  days: Day[] = [];
  /**Available years */
  years: YearItem[] = [];
  /**Selected start date */
  startDate: Date | null = null;
  /**Selected end date */
  endDate: Date | null = null;
  /* ----- Template references ----- */
  /**Year grid container */
  @ViewChild('yearGrid') yearGrid!: ElementRef;
  /* Lifecycle Hooks */
  /**Initialize calendar */
  ngOnInit() {
    const today = new Date();
    //Default selection
    this.startDate = today;
    //set first day of month
    this.currentMonth = new Date(
      today.getFullYear(),
      today.getMonth(),
      1
    );
    this.tempYear = today.getFullYear();
    this.buildYears();
    this.generateCalendar();
  }

  /**Watch input changes */
  ngOnChanges(changes: SimpleChanges) {
    if (
      changes['noPastYears'] ||
      changes['noFutureYears'] ||
      changes['pastYearLimit'] ||
      changes['futureYearLimit']
    ) {
      this.buildYears();
    }
  }
  /**
   * Toggle calendar popup
   */
  toggle() {
    this.show = !this.show;
  }
  /**Close calendar & year picker */
  close() {
    this.show = false;
    this.showYearPicker = false;
  }
  /* ----- Month navigation ----- */
  /**Navigate to previous month */
  prevMonth() {
    this.currentMonth = new Date(
      this.currentMonth.getFullYear(),
      this.currentMonth.getMonth() - 1,
      1
    );
    this.generateCalendar();
  }
  /**Navigate to next month */
  nextMonth() {
    this.currentMonth = new Date(
      this.currentMonth.getFullYear(),
      this.currentMonth.getMonth() + 1,
      1
    );
    this.generateCalendar();
  }
  /* ----- Calendar Generation ------ */
  /**
   * Generate monthly calendar grid
   */
  generateCalendar() {
    this.days = [];
    const year = this.currentMonth.getFullYear();
    const month = this.currentMonth.getMonth();
    // Week start(Month based)
    const firstDay = new Date(year, month, 1).getDay();
    const startOffset = firstDay === 0 ? 6 : firstDay - 1;
    const totalDays = new Date(year, month + 1, 0).getDate();
    // Previous month fillers
    for (let i = 0; i < startOffset; i++) {
      this.days.push({
        date: new Date(),
        currentMonth: false
      });
    }
    //Current month days
    for (let i = 1; i <= totalDays; i++) {
      const dates = new Date(year, month, i);
      const isStart =
        this.startDate &&
        dates.toDateString() === this.startDate.toDateString();
      const isEnd =
        this.endDate &&
        dates.toDateString() === this.endDate.toDateString();
      this.days.push({
        date: dates,
        currentMonth: true,
        selected: this.isSelected(dates),
        inRange: this.isInRange(dates),
        rangeStart: !!isStart,
        rangeEnd: !!isEnd,
      });
    }
    //Next moth fillers
    const remaining = 42 - this.days.length;
    for (let i = 0; i < remaining; i++) {
      this.days.push({
        date: new Date(),
        currentMonth: false
      });
    }
  }
  /* ------ Date selection ----- */
  /**Select a day */
  selectDate(day: Day) {
    if (!day.currentMonth) return;
    //Single mode
    if (this.type === 'single') {
      const selected = new Date(day.date);
      this.startDate = selected;
      this.close();
    }
    //Range mode
    if (this.type === 'range') {
      if (!this.startDate || this.endDate) {
        this.startDate = day.date;
        this.endDate = null;
      } else {
        if (day.date < this.startDate) {
          this.endDate = this.startDate;
          this.startDate = day.date;
        } else {
          this.endDate = day.date;
        }
      }
    }
    this.generateCalendar();
  }
  /* ----- Selection helpers ------ */
  /**Check if date is selected */
  isSelected(date: Date) {
    if (this.type === 'single') {
      return (
        this.startDate?.toDateString() ===
        date.toDateString()
      );
    }
    return (
      this.startDate?.toDateString() ===
      date.toDateString() ||
      this.endDate?.toDateString() ===
      date.toDateString()
    );
  }
  /**Check if date is in range */
  isInRange(date: Date) {
    if (!this.startDate || !this.endDate) return false;
    return date > this.startDate && date < this.endDate;
  }
  /* ----- Display helpers ----- */
  /**
   * Display value in input
   */
  get displayValue() {
    if (this.type === 'single') {
      return this.startDate
        ? this.format(this.startDate)
        : '';
    }
    if (this.startDate && this.endDate) {
      return `${this.format(this.startDate)} To ${this.format(this.endDate)}`;
    }
    return '';
  }
  /**Format date string */
  format(d: Date) {
    const day = d.toLocaleDateString('en-GB', { day: '2-digit' });
    const month = d.toLocaleDateString('en-GB', { month: 'short' });
    const year = d.getFullYear();
    return `${day}-${month}-${year}`;
  }
  /* ----- Outside click handler ----- */
  /**Close picker on outside click */
  @HostListener('document:click', ['$event'])
  clickOutside(e: Event) {
    const target = e.target as HTMLElement;
    if (!target.closest('.date-picker')) {
      this.close();
    }
  }
  /**Build selectable years list */
  buildYears() {
    const current = new Date().getFullYear();
    const pastLimit =
      this.pastYearLimit !== null
        ? Number(this.pastYearLimit)
        : null;
    const futureLimit =
      this.futureYearLimit !== null
        ? Number(this.futureYearLimit)
        : null;
    const start = 1900;
    const end = 2100;
    this.years = [];
    for (let i = start; i <= end; i++) {
      let disabled = false;
      if (this.noPastYears && i < current) {
        disabled = true;
      }
      if (this.noFutureYears && i > current) {
        disabled = true;
      }
      if (
        !this.noPastYears &&
        pastLimit !== null &&
        i < current - pastLimit
      ) {
        disabled = true;
      }
      if (
        !this.noFutureYears &&
        futureLimit !== null &&
        i > current + futureLimit
      ) {
        disabled = true;
      }
      this.years.push({
        value: i,
        disabled
      });
    }
    //Reset invalid year
    const valid = this.years.find(
      year => year.value === this.tempYear && !year.disabled
    );
    if (!valid) {
      this.tempYear = current;
    }
  }
  /**Open year selector */
  openYearPicker() {
    const current = new Date().getFullYear();
    this.tempYear = current;
    this.showYearPicker = true;
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        this.scrollToYear();
      });
    });
  }
  /**Scroll to selected year */
  scrollToYear() {
    if (!this.yearGrid) return;
    const current = new Date().getFullYear();
    const items =
      this.yearGrid.nativeElement.querySelectorAll(
        '.year-item'
      );
    if (!items || !items.length) return;
    const index = this.years.findIndex(
      year => year.value === current
    );
    if (index === -1) return;
    const el = items[index] as HTMLElement;
    el.scrollIntoView({
      behavior: 'auto',
      block: 'center'
    });
  }
  /**Cancel year selection */
  cancelYear() {

    this.showYearPicker = false;
  }
  /**Apply selected year */
  selectYear() {
    const selected = this.years.find(
      year => year.value === this.tempYear
    );
    if (!selected || selected.disabled) return;
    this.currentMonth = new Date(
      this.tempYear,
      this.currentMonth.getMonth(),
      1
    );
    this.generateCalendar();
    this.showYearPicker = false;
  }
}

import { Component, Input } from '@angular/core';
import { FormsModule } from '@angular/forms';
export interface DonutSegment {
  value: number;
  color: string;
}
@Component({
  selector: 'app-donut-pie',
  imports: [FormsModule],
  templateUrl: './donut-pie.html',
  styleUrl: './donut-pie.scss',
})
export class DonutPie {
  /** Chart size */
  @Input() size = 300;
  /** Pie segments */
  @Input() segments: DonutSegment[] = [];
  /**Get total segment value */
  getTotal(): number {
    return this.segments.reduce((a, b) => a + b.value, 0);
  }
  /**Convert value to angle */
  getAngle(value: number): number {
    return (value / this.getTotal()) * 360;
  }
  /**Get start angle for segment */
  getStart(index: number): number {
    let total = 0;
    for (let i = 0; i < index; i++) {
      total += this.getAngle(this.segments[i].value);
    }
    return total;
  }
  /* ================== SVG PATH ================== */
  getArcPath(startAngle: number, angle: number): string {
    const rOuter = this.size / 2;
    const rInner = rOuter - 100;
    const cx = this.size / 2;
    const cy = this.size / 2;
    const toRad = (deg: number) => (deg * Math.PI) / 180;
    const start = toRad(startAngle - 90);
    const end = toRad(startAngle + angle - 90);
    const startX = cx + rOuter * Math.cos(start);
    const startY = cy + rOuter * Math.sin(start);
    const endX = cx + rOuter * Math.cos(end);
    const endY = cy + rOuter * Math.sin(end);
    const innerEndX = cx + rInner * Math.cos(end);
    const innerEndY = cy + rInner * Math.sin(end);
    const innerStartX = cx + rInner * Math.cos(start);
    const innerStartY = cy + rInner * Math.sin(start);
    const largeArc = angle > 180 ? 1 : 0;
    return `
      M ${startX} ${startY}
      A ${rOuter} ${rOuter} 0 ${largeArc} 1 ${endX} ${endY}
      L ${innerEndX} ${innerEndY}
      A ${rInner} ${rInner} 0 ${largeArc} 0 ${innerStartX} ${innerStartY}
      Z
    `;
  }
}

import { Component, Input } from '@angular/core';
export interface MultiRingItem {
  label: string;
  value: number;
  color: string;
}
@Component({
  selector: 'app-multi-ring-pie',
  imports: [],
  templateUrl: './multi-ring-pie.html',
  styleUrl: './multi-ring-pie.scss',
})
export class MultiRingPie {
  /** Chart size */
  @Input() size = 300;

  /** Rings data */
  @Input() rings: MultiRingItem[] = [];
  tooltipVisible = false;
  tooltipX = 0;
  tooltipY = 0;
  tooltipData: any = null;
  /** Selected ring */
  selectedIndex: number | null = null;
  getRingRadius(index: number): number {
    const base = this.size / 2 - 30;
    return base - index * 28;
  }

  getRingCircumference(r: number): number {
    return 2 * Math.PI * r;
  }

  getRingOffset(value: number, r: number): number {
    const c = this.getRingCircumference(r);
    return c * (1 - value / 100);
  }

  selectRing(index: number) {
    this.selectedIndex = index;
  }
  // Show tooltip
  showTooltip(event: MouseEvent, ring: any) {
    this.tooltipVisible = true;
    this.tooltipX = event.clientX;
    this.tooltipY = event.clientY;
    this.tooltipData = ring;
  }

  // Hide tooltip
  hideTooltip() {
    this.tooltipVisible = false;
  }
}

import { Component, Input } from '@angular/core';
/**Child navigation item */
export interface NavChild {
  label: string;
  icon?: string;
}
/**Parent navigation item */
export interface NavItem {
  icon: string;
  label: string;
  children?: NavChild[];
}
@Component({
  selector: 'app-navigation',
  imports: [],
  templateUrl: './navigation.html',
  styleUrl: './navigation.scss',
})
export class Navigation {
  /* ----- Inputs ----- */
  /**Sidebar expanded or collapsed state */
  @Input() expanded = false;
  /**Show parent icons */
  @Input() showParentIcons = true;
  /**Show child icons */
  @Input() showChildIcons = true;
  /**Show app logo */
  @Input() showLogo = true;
  /**Currently active parent index */
  @Input() activeIndex: number | null = null;
  /**Currently open accordion index */
  @Input() openIndex: number | null = null;
  /**Enable slider mode */
  @Input() useSlider = false;
  /* ----- Internal states ----- */
  /**Currently hovered parent index */
  hoveredIndex: number | null = null;
  /**Active child item reference */
  activeChild: { parent: number; index: number } | null = null;
  /**Navigation item list */
  navItems: NavItem[] = [];
  /**Vertical hover indicator position */
  hoverY = 0;
  /**Hover panel top offset */
  panelTop: number = 0;
  /**Handle parent item hover */
  onHover(index: number, event: MouseEvent) {
    const target = event.currentTarget as HTMLElement;
    const rect = target.getBoundingClientRect();
    this.panelTop = rect.top;
    this.hoveredIndex = index;
    this.hoverY = rect.top + rect.height / 2;
  }
  /**Handle hover child click */
  onHoverChildClick(parentIndex: number, childIndex: number) {
    this.expanded = true;
    this.activeIndex = parentIndex;
    this.openIndex = parentIndex;
    this.activeChild = {
      parent: parentIndex,
      index: childIndex,
    };
    this.hoveredIndex = null;
  }
  /**Handle parent item click */
  onParentClick(index: number, hasChildren: boolean) {
    if (this.openIndex === index) {
      this.openIndex = null;
      this.activeChild = null;
      return;
    }
    this.activeIndex = index;
    if (hasChildren) {
      this.openIndex = index;
      this.activeChild = {
        parent: index,
        index: 0
      };
    } else {
      this.openIndex = null;
      this.activeChild = null;
    }
  }
  /**Toggle sidebar expand/ collapse */
  toggle() {
    this.expanded = !this.expanded;
    if (!this.expanded) {
      this.activeIndex = null;
      this.openIndex = null;
      this.activeChild = null;
    }
  }
  /**Toggle parent item active state */
  toggleItem(index: number) {
    this.activeIndex = this.activeIndex === index ? null : index;
    this.activeChild = null;
  }
  /**Select child item */
  selectChild(parentIndex: number, childIndex: number) {
    this.activeIndex = parentIndex;
    this.activeChild = {
      parent: parentIndex,
      index: childIndex
    };
  }
}

