import { CommonModule } from '@angular/common';
import { AfterContentInit, Component, ContentChild, ContentChildren, ElementRef, Input, QueryList } from '@angular/core';
import { Checkbox } from '../checkbox/checkbox';
import { MultiSelectDropdown } from '../multi-select-dropdown/multi-select-dropdown';
import { Search } from '../search/search';

@Component({
  selector: 'app-accordion',
  imports: [CommonModule, Checkbox, MultiSelectDropdown, Search],
  templateUrl: './accordion.html',
  styleUrl: './accordion.scss',
})
export class Accordion implements AfterContentInit {
  // Input for title 
  @Input() title!: string;
  // Input for types of variants
  @Input() type: 'primary' | 'secondary' = 'primary';
  //Input for expanded true or false
  @Input() expanded = false;
  hasProjectedContent = false;
  @ContentChild('projected', { read: ElementRef })
  projectedContent!: ElementRef;
  ngAfterContentInit() {
    this.hasProjectedContent = !!this.projectedContent;
  }
  /**
   * Toggle function to expand or collapse accordion
   */
  public toggle(): void {
    this.expanded = !this.expanded;
  }
}

import { CommonModule } from '@angular/common';
import { Component, EventEmitter, Input, Output, signal } from '@angular/core';
import { CloseButton } from "../close-button/close-button";

@Component({
  selector: 'app-alert',
  imports: [CommonModule, CloseButton],
  templateUrl: './alert.component.html',
  styleUrl: './alert.component.scss',
  host: {
    '(mouseenter)': 'pauseAutoClose()',
    '(mouseleave)': 'resumeAutoClose()',
    '(document:keydown.escape)': 'handleEsc()'
  }
})
export class Alert {
  //#region Inputs
  /** Message to display */
  @Input() message = 'This is an alert message';
  /** Optional title for the alert */
  @Input() title?: string;
  /** Type of alert */
  @Input() type: 'success' | 'info' | 'warning' | 'error' = 'info';
  /** Show icon in the alert */
  @Input() showIcon = true;
  /** Whether the alert can be closed */
  @Input() isClosable = true;
  /** Auto close the alert after a delay */
  @Input() autoClose = false;
  /** Delay in milliseconds before auto-closing */
  @Input() autoCloseDelay = 4000;
  /** Size of the alert */
  @Input() size: 'sm' | 'md' | 'lg' = 'md';
  /** Background color of the alert */
  @Input() backgroundColor?: string;
  /** Text color of the alert */
  @Input() textColor?: string;
  /** Border radius of the alert */
  @Input() rounded: 'none' | 'md' | 'lg' | 'pill' = 'md';
  /** Elevation level of the alert */
  @Input() elevation = 0;
  /** Animation type for alert appearance */
  @Input() animation: 'fade' | 'slide' | 'scale' = 'fade';
  //#endregion

  //#region Outputs
  @Output() onClose = new EventEmitter<void>();
  @Output() onActionClick = new EventEmitter<void>();
  @Output() onTimeout = new EventEmitter<void>();
  @Output() onRender = new EventEmitter<void>();
  //#endregion

  //#region Properties
  private timeout!: any;
  public isVisible = signal(true);
  //#endregion

  //#region Lifecycle Hooks
  /** OnInit Lifecycle Hook */
  public ngOnInit(): void {
    this.onRender.emit();

    if (this.autoClose) {
      this.startTimer();
    }
  }
  //#endregion

  //#region Methods
  /** Get the icon path based on alert type */
  public get iconPath(): string {
    return `assets/icons/${this.type}.svg`;
  }

  /** Start the auto-close timer */
  public startTimer(): void {
    this.timeout = setTimeout(() => {
      this.close(true);
    }, this.autoCloseDelay);
  }

  /** Pause the auto-close timer */
  public pauseAutoClose(): void {
    if (this.timeout) clearTimeout(this.timeout);
  }

  /** Resume the auto-close timer */
  public resumeAutoClose(): void {
    if (this.autoClose) this.startTimer();
  }

  /** Close the alert */
  public close(isTimeout = false): void {
    this.isVisible.set(false);
    this.onClose.emit();
    if (isTimeout) this.onTimeout.emit();
  }

  /** Handle Escape key press to close alert */
  public handleEsc(): void {
    if (this.isClosable) this.close();
  }

  /** Cleanup on component destroy */
  public ngOnDestroy(): void {
    clearTimeout(this.timeout);
  }
}
//#endregion

components.templateData:
@if(isVisible()) {
<div
[class.hide]="!isVisible()"
  class="storybook-alert"
  role="alert"
  aria-live="assertive"
  [ngClass]="[
    'storybook-alert--' + type,
    'storybook-size-' + size,
    'storybook-rounded-' + rounded,
    'storybook-shadow-' + elevation,
    'storybook-anim-' + animation
  ]"
  [style.background-color]="backgroundColor"
  [style.color]="textColor">

  @if(showIcon) {
  <img
       [src]="iconPath" 
       class="storybook-alert-icon"
       alt="{{ type }} icon" />
  }

  @if (title) {
    <strong class="storybook-alert-title">
      {{ title }}
    </strong>
  }

  <span class="storybook-alert-message">
    {{ message }}
  </span>

  @if(isClosable) {
  <app-close-button
          class="storybook-alert-close-icon"
          aria-label="Close alert"
          (click)="close()">
  </app-close-button>
}
</div>
}

