export interface MultiRingItem {
  label: string;
  value: number;
  color: string;
}
@Component({
  selector: 'app-multi-ring-pie',
  imports: [],
  templateUrl: './multi-ring-pie.html',
  styleUrl: './multi-ring-pie.scss',
})
export class MultiRingPie {
  /** Chart size */
  @Input() size = 300;

  /** Rings data */
  @Input() rings: MultiRingItem[] = [];
  tooltipVisible = false;
  tooltipX = 0;
  tooltipY = 0;
  tooltipData: any = null;
  /** Selected ring */
  selectedIndex: number | null = null;
  getRingRadius(index: number): number {
    const base = this.size / 2 - 30;
    return base - index * 28;
  }

  getRingCircumference(r: number): number {
    return 2 * Math.PI * r;
  }

  getRingOffset(value: number, r: number): number {
    const c = this.getRingCircumference(r);
    return c * (1 - value / 100);
  }

  selectRing(index: number) {
    this.selectedIndex = index;
  }
  // Show tooltip
  showTooltip(event: MouseEvent, ring: any) {
    this.tooltipVisible = true;
    this.tooltipX = event.clientX;
    this.tooltipY = event.clientY;
    this.tooltipData = ring;
  }

  // Hide tooltip
  hideTooltip() {
    this.tooltipVisible = false;
  }
}

import { CommonModule } from '@angular/common';
import { Component, ElementRef, HostListener, Input, OnInit, OnChanges, SimpleChanges, Output, EventEmitter } from '@angular/core';
import { Checkbox } from '../checkbox/checkbox';
import { Tooltip } from '../tooltip/tooltip';

@Component({
  selector: 'app-multi-select-dropdown',
  imports: [CommonModule, Checkbox, Tooltip],
  templateUrl: './multi-select-dropdown.html',
  styleUrl: './multi-select-dropdown.scss',
})
export class MultiSelectDropdown implements OnInit, OnChanges {
  constructor(private element: ElementRef) { }
  /* ----- Inputs -----*/
  /**Field label text */
  @Input() label = '';
  /**Available dropdown options */
  @Input() options: string[] = [];
  /**Disable dropdown interaction */
  @Input() disabled = false;
  /**Make dropdown readonly */
  @Input() readonly = false;
  /**Validation error message */
  @Input() error = '';
  /**Mark field as required */
  @Input() required = true;
  /**Currently selected values */
  @Input() selected: string[] = [];
  /**Placeholder text */
  @Input() placeholder = 'Select Items';
  /**Dropdown icon path */
  @Input() dropdownIcon: string = 'assets/icons/dropdown.svg';
  /**Dropdown behavior mode
   * dropdown -> normal
   * search -> searchable
   */
  @Input() mode: 'dropdown' | 'search' = 'dropdown';
  /* ----- Outputs ----- */
  /**Emits when selection changes */
  @Output() selectedChange = new EventEmitter<string[]>();
  /* ----- Internal States ----- */
  /**Dropdown open state */
  isOpen = false;
  /**Focus state */
  isFocused = false;
  /**Filtered options list */
  filteredOptions: string[] = [];
  /* ----- Lifecycle hooks ----- */
  /**Initialize component */
  ngOnInit(): void {
    this.filteredOptions = [...this.options];
  }
  /**Handle input changes */
  ngOnChanges(changes: SimpleChanges): void {
    if (changes['options']) {
      this.filteredOptions = [...this.options];
    }
    if (changes['selected']) {
      this.selected = [...this.selected];
    }
  }
  /**Handle main field click */
  public handleClick(): void {
    if (this.disabled || this.readonly) return;
    if (this.mode === 'dropdown') {
      this.isOpen = !this.isOpen;
    }
    if (this.mode === 'search') {
      this.isOpen = true;
    }
    this.isFocused = this.isOpen;
    this.filteredOptions = [...this.options];
  }
  /**Toggle item selection */
  toggleSelect(item: string) {
    const updated = this.selected.includes(item)
      ? this.selected.filter(i => i !== item)
      : [...this.selected, item];

    this.selected = updated;
    this.selectedChange.emit(updated);
  }
  /**Remove selected item */
  removeSelected(item: string) {
    this.selected = this.selected.filter(i => i !== item);
    this.selectedChange.emit(this.selected);
  }
  /**Filter options based on input */
  filterOptions(event: Event): void {
    const value = (event.target as HTMLInputElement).value.toLowerCase();
    this.filteredOptions = this.options.filter(opt =>
      opt.toLowerCase().includes(value)
    );
  }
  /**Truncate long options */
  truncate(value: string, limit = 10): string {
    return value.length > limit
      ? value.slice(0, limit) + '…'
      : value;
  }
  /**Close dropdown on outside click */
  @HostListener('document:click', ['$event'])
  onDocumentClick(event: MouseEvent): void {
    const clickedInside = this.element.nativeElement.contains(event.target);
    if (!clickedInside && this.isOpen) {
      this.isOpen = false;
      this.isFocused = false;
    }
  }
}

import { Component, Input } from '@angular/core';
/**Child navigation item */
export interface NavChild {
  label: string;
  icon?: string;
}
/**Parent navigation item */
export interface NavItem {
  icon: string;
  label: string;
  children?: NavChild[];
}
@Component({
  selector: 'app-navigation',
  imports: [],
  templateUrl: './navigation.html',
  styleUrl: './navigation.scss',
})
export class Navigation {
  /* ----- Inputs ----- */
  /**Sidebar expanded or collapsed state */
  @Input() expanded = false;
  /**Show parent icons */
  @Input() showParentIcons = true;
  /**Show child icons */
  @Input() showChildIcons = true;
  /**Show app logo */
  @Input() showLogo = true;
  /**Currently active parent index */
  @Input() activeIndex: number | null = null;
  /**Currently open accordion index */
  @Input() openIndex: number | null = null;
  /**Enable slider mode */
  @Input() useSlider = false;
  /* ----- Internal states ----- */
  /**Currently hovered parent index */
  hoveredIndex: number | null = null;
  /**Active child item reference */
  activeChild: { parent: number; index: number } | null = null;
  /**Navigation item list */
  navItems: NavItem[] = [];
  /**Vertical hover indicator position */
  hoverY = 0;
  /**Hover panel top offset */
  panelTop: number = 0;
  /**Handle parent item hover */
  onHover(index: number, event: MouseEvent) {
    const target = event.currentTarget as HTMLElement;
    const rect = target.getBoundingClientRect();
    this.panelTop = rect.top;
    this.hoveredIndex = index;
    this.hoverY = rect.top + rect.height / 2;
  }
  /**Handle hover child click */
  onHoverChildClick(parentIndex: number, childIndex: number) {
    this.expanded = true;
    this.activeIndex = parentIndex;
    this.openIndex = parentIndex;
    this.activeChild = {
      parent: parentIndex,
      index: childIndex,
    };
    this.hoveredIndex = null;
  }
  /**Handle parent item click */
  onParentClick(index: number, hasChildren: boolean) {
    if (this.openIndex === index) {
      this.openIndex = null;
      this.activeChild = null;
      return;
    }
    this.activeIndex = index;
    if (hasChildren) {
      this.openIndex = index;
      this.activeChild = {
        parent: index,
        index: 0
      };
    } else {
      this.openIndex = null;
      this.activeChild = null;
    }
  }
  /**Toggle sidebar expand/ collapse */
  toggle() {
    this.expanded = !this.expanded;
    if (!this.expanded) {
      this.activeIndex = null;
      this.openIndex = null;
      this.activeChild = null;
    }
  }
  /**Toggle parent item active state */
  toggleItem(index: number) {
    this.activeIndex = this.activeIndex === index ? null : index;
    this.activeChild = null;
  }
  /**Select child item */
  selectChild(parentIndex: number, childIndex: number) {
    this.activeIndex = parentIndex;
    this.activeChild = {
      parent: parentIndex,
      index: childIndex
    };
  }
}

