    <div class="table-row menu-row">
        <div class="cell link">
            <a href="#">{{ row.link }}</a>
        </div>
        <div class="cell">{{ row.date }}</div>
        <div class="cell">{{ row.v1 }}</div>
        <div class="cell">{{ row.date }}</div>
        <div class="cell">{{ row.v2 }}</div>
        <div class="cell">{{ row.v1 }}</div>
        <div class="cell">{{ row.date }}</div>
        <div class="cell">{{ row.v2 }}</div>
        <div class="cell status">
            <app-status-chips mode="single" [label]="row.status" [status]="getRowStatus(row.status)" styleType="DotStyle">
            </app-status-chips>
        </div>
        <div class="cell menu">
            <button class="menu-btn" (click)="toggleMenu(row, $event)">
                <img src="assets/icons/breadcrumb.svg" />
            </button>
            @if (row.menuOpen) {
            <div class="menu-dropdown">
                <div class="menu-item" (click)="onEdit(row)">
                    Edit
                </div>
                <div class="menu-item danger" (click)="onDelete(row)">
                    Delete
                </div>
                <div class="menu-item" (click)="onTrack(row)">
                    Track
                </div>
            </div>
            }
        </div>
    </div>
    }
</div>
}

