import { CommonModule } from '@angular/common';
import { Component, Input } from '@angular/core';
/* Tab item definition */
export interface TabItem {
  label: string;
  icon?: string;
}

@Component({
  selector: 'app-tabs',
  imports: [CommonModule],
  templateUrl: './tabs.html',
  styleUrl: './tabs.scss',
})
export class Tabs {
  /* ----- Inputs ----- */
  /** Tabs configuration list */
  @Input() tabs: TabItem[] = [];
  /** Tabs visual variants*/
  @Input() variant: string = 'style-1';
  /** Toggle icon visibility */
  @Input() showIcon: boolean = true;
  /**Currently active tab index */
  activeIndex = 0;
  /**Select a tab */
  selectTab(index: number) {
    this.activeIndex = index;
  }
}

import { Component, Input } from '@angular/core';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-temperature-pie',
  imports: [FormsModule],
  templateUrl: './temperature-pie.html',
  styleUrl: './temperature-pie.scss',
})
export class TemperaturePie {
  @Input() size = 180;
  @Input() minTemp = 10;
  @Input() maxTemp = 30;
  currentTemp = 16;
  isPowerOn = true;
  segmentsCount = 30;
  get activeSegments() {
    const range = this.maxTemp - this.minTemp;
    const value = this.currentTemp - this.minTemp;
    return Math.round((value / range) * this.segmentsCount);
  }
  get segmentArray() {
    return Array(this.segmentsCount).fill(0);
  }
  /**Increase Temperature */
  increaseTemp() {
    if (!this.isPowerOn) return;

    if (this.currentTemp < this.maxTemp) {
      this.currentTemp++;
    }
  }
  /**Decrease Temperature */
  decreaseTemp() {
    if (!this.isPowerOn) return;
    if (this.currentTemp > this.minTemp) {
      this.currentTemp--;
    }
  }
  /**Toggle power */
  togglePower() {
    this.isPowerOn = !this.isPowerOn;
  }
}

import { CommonModule } from '@angular/common';
import { Component, EventEmitter, Input, Output } from '@angular/core';

@Component({
  selector: 'app-toast',
  imports: [CommonModule],
  templateUrl: './toast.html',
  styleUrl: './toast.scss',
})
export class Toast {
  /* ----- Inputs ----- */
  /**Toast visual variants */
  @Input() variant: 'progress' | 'success' | 'warning' | 'error' = 'progress';
  /**Title for toast */
  @Input() title = '';
  /**Message for toast */
  @Input() message = '';
  /**Sub title for toast */
  @Input() subTitle = '';
  /**Position for the toast */
  @Input() position: | 'left-top' | 'left-bottom' | 'right-top' | 'right-bottom' | 'center-top' | 'center-bottom' = 'left-top';
  /* ----- Outputs ----- */
  /**Emit close */
  @Output() close = new EventEmitter<void>();
}

import { CommonModule } from '@angular/common';
import { Component, EventEmitter, Input, Output } from '@angular/core';
import { Tooltip } from '../tooltip/tooltip';

@Component({
  selector: 'app-toggle',
  imports: [CommonModule, Tooltip],
  templateUrl: './toggle.html',
  styleUrl: './toggle.scss',
})
export class Toggle {
  /* ----- Inputs ----- */
  /**Toggle size */
  @Input() size: 'sm' | 'md' = 'sm';
  /**Toggle state */
  @Input() checked: boolean | null = null;
  /**Disable interaction */
  @Input() disabled = false;
  /**Show ON/OFF text */
  @Input() showText = false;
  /**Toggle visual variant */
  @Input() variant: 'default' | 'iconic' | 'text' = 'default';
  /**Text when toggle is on */
  @Input() onText = 'Toggle on';
  /**Text when toggle off */
  @Input() offText = 'Toggle off';
  /**Left label */
  @Input() leftText = 'Table';
  /**Right label */
  @Input() rightText = 'Gallery';
  /* ----- Output ----- */
  /**Emit when toggle state changes */
  @Output() changed = new EventEmitter<boolean | null>();
  /**Display text based on state */
  get displayText(): string {
    if (this.checked === true) return this.onText;
    if (this.checked === false) return this.offText;
    return '';
  }
  /**Set toggle value manually */
  setValue(value: boolean | null) {
    if (this.disabled) return;
    this.checked = value;
    this.changed.emit(this.checked);
  }
  /**Toggle between ON/OFF */
  onToggle() {
    if (this.disabled) return;
    this.checked = !this.checked;
    this.changed.emit(this.checked);
  }
  /**Toggle in iconic mode */
  toggleIconic(value: boolean) {
    if (this.disabled) return;
    if (this.checked === value) {
      this.checked = null;
    } else {
      this.checked = value;
    }
    this.changed.emit(this.checked);
  }
  /**Truncate long text */
  getTruncatedText(text: string): string {
    if (!text) return '';
    return text.length > 10 ? text.slice(0, 10) + '…' : text;
  }
  /**Check if text is long */
  isLongText(text: string): boolean {
    return !!text && text.length > 10;
  }
}

